106	template<>
107	struct type_caster<priv::ExternalStream<priv::VOIDP>>
108	{
109	    PYBIND11_TYPE_CASTER(priv::ExternalStream<priv::VOIDP>, const_name("ctypes.c_void_p"));
110	
111	    bool load(handle src, bool)
112	    {
113	        if (std::string strType = util::GetFullyQualifiedName(src); strType != "ctypes.c_void_p")
114	        {
115	            return false;
116	        }
117	
118	        buffer_info info = ::pybind11::cast<buffer>(src).request();
119	
120	        NVCV_ASSERT(info.itemsize == sizeof(void *));
121	
122	        void *data = *reinterpret_cast<void **>(info.ptr);
123	
124	        value.setCudaStream(reinterpret_cast<cudaStream_t>(data), ::pybind11::cast<object>(src));
125	        return true;
126	    }
127	};
