130	struct type_caster<priv::ExternalStream<priv::INT>>
131	{
132	    PYBIND11_TYPE_CASTER(priv::ExternalStream<priv::INT>, const_name("int"));
133	
134	    bool load(handle src, bool)
135	    {
136	        try
137	        {
138	            // REVISIT: don't know how to test if a python object
139	            // is convertible to a type without exceptions.
140	            intptr_t data = src.cast<intptr_t>();
141	            value.setCudaStream(reinterpret_cast<cudaStream_t>(data), ::pybind11::cast<object>(src));
142	            return true;
143	        }
144	        catch (...) // NOSONAR: pybind type casters probe conversions by catching failures.
145	        {
146	            return false;
147	        }
148	    }
149	};
