369	void Stream::destroy()
370	{
371	    if (m_owns && m_handle)
372	    {
373	        int savedDev = 0;
374	        util::CheckLog(cudaGetDevice(&savedDev));
375	        util::CheckLog(cudaSetDevice(m_key.deviceId()));
376	        util::CheckLog(cudaStreamSynchronize(m_handle));
377	        util::CheckLog(cudaStreamDestroy(m_handle));
378	        util::CheckLog(cudaSetDevice(savedDev));
379	        m_handle = nullptr;
380	    }
381	    {
382	        std::unique_lock lock(m_auxStreamMutex);
383	        if (decrementInstanceCount() == 0)
384	        {
385	            int savedDev = 0;
386	            util::CheckLog(cudaGetDevice(&savedDev));
387	            for (const auto &[dev, auxStream] : m_auxStreams)
388	            {
389	                util::CheckLog(cudaSetDevice(dev));
390	                util::CheckLog(cudaStreamSynchronize(auxStream));
391	                util::CheckLog(cudaStreamDestroy(auxStream));
392	            }
393	            m_auxStreams.clear();
394	            util::CheckLog(cudaSetDevice(savedDev));
395	        }
396	    }
397	    {
398	        std::lock_guard lock(m_eventMutex);
399	        int             savedDev = 0;
400	        util::CheckLog(cudaGetDevice(&savedDev));
401	        for (const auto &[dev, evt] : m_events)
402	        {
403	            util::CheckLog(cudaSetDevice(dev));
404	            util::CheckLog(cudaEventDestroy(evt));
405	        }
406	        m_events.clear();
407	        util::CheckLog(cudaSetDevice(savedDev));
408	    }
409	}
