509	// Stores the data held by a cuda host callback function in a cuda stream.
510	// It's used for:
511	// - Extend the lifetime of the objects it contains until they aren't needed
512	//   by any future cuda kernels in the stream.
513	struct Stream::HostFunctionClosure
514	{
515	    // Also hold the stream reference so that it isn't destroyed before the processing is done.
516	    std::shared_ptr<const Stream> stream;
517	    LockResources                 resources;
518	};
519	
520	cudaEvent_t Stream::getEvent()
521	{
522	    int dev;
523	    util::CheckThrow(cudaGetDevice(&dev));
524	
525	    {
526	        std::shared_lock lock(m_eventMutex);
527	        auto             it = m_events.find(dev);
528	        if (it != m_events.end())
529	            return it->second;
530	    }
531	
532	    std::unique_lock lock(m_eventMutex);
533	    auto [it, inserted] = m_events.try_emplace(dev, nullptr);
534	    if (inserted)
535	    {
536	        cudaEvent_t evt = nullptr;
537	        util::CheckThrow(cudaEventCreateWithFlags(&evt, cudaEventDisableTiming));
538	        it->second = evt;
539	    }
540	    return it->second;
541	}
542	
543	void Stream::holdResources(LockResources usedResources)
544	{
545	    if (!usedResources.empty())
546	    {
547	        // Looks like a good place to clear the gc bag, as every time we create
548	        // a new closure that eventually gets added to the bag, we empty it.
549	        // The bag shouldn't grow unlimited.
550	        // Calling it before allocating a new closure just avoid having two
551	        // closures not inside a cuda stream that are simultaneously alive, but
552	        // in practice it doesn't seem to matter much.
553	        ClearGCBag();
554	
555	        auto closure = std::make_unique<HostFunctionClosure>();
556	
557	        closure->stream    = this->sharedStream();
558	        closure->resources = std::move(usedResources);
559	
560	        auto fn = [](cudaStream_t, cudaError_t, auto *userData)
561	        {
562	            std::unique_ptr<HostFunctionClosure> pclosure(static_cast<HostFunctionClosure *>(userData));
563	            NVCV_ASSERT(pclosure != nullptr);
564	            AddToGCBag(std::move(pclosure));
565	        };
566	
567	        // If we naively execute the callback in the main stream (m_handle), the GPU will wait until the callback
568	        // is executed (on host). For correctness, GPU doesn't need to wait - it's the CPU that needs
569	        // to wait for the work already scheduled to complete.
570	        //
571	        // Naive timeline:
572	        //
573	        // stream        GPU_kernel1 | Callback | GPU_kernel2
574	        // GPU activity  xxxxxxxxxxx              xxxxxxxxxxx
575	        // CPU activity                xxxxxxxx
576	        //
577	        // Optimized timeline
578	        //
579	        //
580	        //                event -----v
581	        // stream        GPU_kernel1 | GPU_kernel2
582	        // aux_stream     waitEvent >| Callback
583	        //
584	        // GPU activity  xxxxxxxxxxx   xxxxxxxxxxx
585	        // CPU activity                xxxxxxxx
586	
587	        cudaEvent_t evt = getEvent();
588	        util::CheckThrow(cudaEventRecord(evt, m_handle));           // add async record the event in the main stream
589	        util::CheckThrow(cudaStreamWaitEvent(GetAuxStream(), evt)); // add async wait for the event in the aux stream
590	
591	        // cudaStreamAddCallback pushes a task to the given stream, which at some point (asynchonously) calls
592	        // the given callback (fn), passing to it the closure we created, among other stream states.
593	        // When fn is executed, the refcnt of all objects that the closure holds will eventually be decremented, which
594	        // will trigger their deletion if refcnt==0. This effectively extends the objects' lifetime until
595	        // all tasks that refer to them are finished.
596	
597	        // The callback will be executed in the singleton aux stream there may be contention with other callbacks and waitEvents from
598	        // other streams. However the callback is used to release resources from the cache and should not be a performance bottleneck.
599	        // This avoids opening a new aux stream for each stream object.
600	
601	        // NOTE: cudaStreamAddCallback is slated for deprecation, without a proper replacement (for now).
602	        // The other option we could use is cudaLaunchHostFunc, but it doesn't guarantee that the callback
603	        // will be called. We need this guarantee to make sure the object's refcount is eventually decremented,
604	        // and the closure is freed, avoiding memory leaks.
605	        // cudaLaunchHostFunc won't call the callback if the current cuda context is in error state, for instance.
606	        // Ref: CUDA SDK docs for both functions.
607	        util::CheckThrow(
608	            cudaStreamAddCallback(GetAuxStream(), fn, closure.get(), 0)); // add async callback in the aux stream
609	        closure.release();
610	    }
611	}
612	
613	Stream::GCBag &Stream::GetGCBag()
614	{
615	    // By defining the gcBag inside this function instead of the global scope,
616	    // we guarantee that it'll be destroyed *before* the global python context
617	    // is destroyed. This is due to this function being called the first time
618	    // (via AddToGCBag or ClearGCBag) only after the python script (and python
619	    // ctx) has already started.
620	    //
621	    // Multi-GPU safety: this is a single process-wide bag holding closures from
622	    // all devices. This is safe because access is serialized by m_gcMutex, and
623	    // each HostFunctionClosure holds a shared_ptr<const Stream> whose destroy()
624	    // properly saves/restores the CUDA device before freeing device resources.
625	    static GCBag gcBag;
626	    return gcBag;
627	}
628	
629	void Stream::AddToGCBag(std::unique_ptr<HostFunctionClosure> closure)
630	{
631	    std::unique_lock lk(m_gcMutex);
632	    GetGCBag().push_back(std::move(closure));
633	}
634	
635	void Stream::ClearGCBag()
636	{
637	    GCBag objectsToBeDestroyed;
638	
639	    GCBag &gcBag = GetGCBag();
640	
641	    std::unique_lock lk(m_gcMutex);
642	    // Do as little as possible while mutex is locked to avoid
643	    // deadlocks.
644	
645	    // In the case here, instead of simply empting up the gc bag,
646	    // which might trigger object destruction while the mutex is locked,
647	    // we move its contents to a temporary local bag.
648	
649	    // take of benefit of ADL if available
650	    using std::swap;
651	    swap(objectsToBeDestroyed, gcBag);
652	
653	    // Now the original bag is left empty, but no objects were
654	    // destroyed yet.
655	    NVCV_ASSERT(gcBag.empty()); // post-condition (can't be guaranteed after unlock)
656	
657	    lk.unlock();
658	
659	    // Let the local object bag go out of scope, the objects in it
660	    // will be finally destroyed with the mutex unlocked.
661	}
662	
663	void Stream::SynchronizeAndClearGCBag()
664	{
665	    bool hasAuxStreams;
666	    {
667	        std::shared_lock lock(m_auxStreamMutex);
668	        hasAuxStreams = !m_auxStreams.empty();
669	    }
670	
671	    if (hasAuxStreams)
672	    {
673	        SyncAuxStream();
674	    }
675	    ClearGCBag();
676	}
677	
678	std::ostream &operator<<(std::ostream &out, const Stream &stream)
679	{
680	    return out << "<nvcv.cuda.Stream id=" << stream.id() << " handle=" << stream.handle() << '>';
681	}
682	
683	template<ExternalStreamType E>
684	static void ExportExternalStream(py::module &m)
685	{
686	    m.def("as_stream",
687	          [](ExternalStream<E> extStream)
688	          {
689	              ::cvcudapy::NvtxRange nvtxRange("cvcuda.as_stream");
690	              return std::make_shared<Stream>(extStream);
691	          });
692	}
693	
694	static void LogCleanupWarning(const std::exception &e)
695	{
696	    std::cerr << "Warning CVCUDA cleanup may be incomplete due to: " << e.what() << std::endl;
697	}
698	
699	void Stream::CleanupAtExit(const std::shared_ptr<Stream> &globalStream)
700	{
701	    // No globalStream means no device at module-init time, no streams were ever
702	    // created, nothing to sync. Cleanup is a no-op.
703	    if (!globalStream)
704	    {
705	        return;
706	    }
707	
708	    try
709	    {
710	        for (std::shared_ptr<Stream> stream : Cache::Instance().fetchAll<Stream>())
711	        {
712	            stream->sync();
713	        }
714	        globalStream->sync();
715	        SyncAuxStream();
716	
717	        // There should only be 1 stream in the stack, namely the global stream.
718	        if (auto s = StreamStack::Instance().top(); s != globalStream)
719	        {
720	            std::cerr << "Stream stack leak detected" << std::endl;
721	        }
722	
723	        // Make sure stream stack is empty.
724	        while (auto s = StreamStack::Instance().top())
725	        {
726	            StreamStack::Instance().pop();
727	        }
728	
729	        // Make sure the gc bag is also cleaned up *after* all streams are done,
730	        // when all remaining items that need to be GC'd are in the bag.
731	        ClearGCBag();
732	    }
733	    catch (const py::error_already_set &e)
734	    {
735	        LogCleanupWarning(e);
736	    }
737	    catch (const StreamError &e)
738	    {
739	        LogCleanupWarning(e);
740	    }
741	    catch (const std::invalid_argument &e)
742	    {
743	        LogCleanupWarning(e);
744	    }
745	    catch (const std::domain_error &e)
746	    {
747	        LogCleanupWarning(e);
748	    }
749	    catch (const std::length_error &e)
750	    {
751	        LogCleanupWarning(e);
752	    }
753	    catch (const std::out_of_range &e)
754	    {
755	        LogCleanupWarning(e);
756	    }
757	    catch (const std::range_error &e)
758	    {
759	        LogCleanupWarning(e);
760	    }
761	    catch (const std::overflow_error &e)
762	    {
763	        LogCleanupWarning(e);
764	    }
765	    catch (const std::underflow_error &e)
766	    {
767	        LogCleanupWarning(e);
768	    }
769	    catch (const std::bad_alloc &e)
770	    {
771	        LogCleanupWarning(e);
772	    }
773	}
774	
775	void Stream::Export(py::module &m)
776	{
777	    py::class_<Stream, std::shared_ptr<Stream>, CacheItem> stream(m, "Stream",
778	                                                                  R"pbdoc(
779	        A CUDA stream that cvcuda operators can be submitted to.
780	
781	        Streams created via ``cvcuda.Stream()`` are non-blocking
782	        (``cudaStreamNonBlocking``) so they can run concurrently with CUDA's
783	        legacy default stream and with other non-blocking streams.
784	
785	        Cross-library stream safety is handled automatically via the CUDA
786	        Array Interface (CAI) v3 ``stream`` field:
787	
788	        * On **input**, ``cvcuda.as_tensor`` / ``cvcuda.as_image`` read
789	          ``__cuda_array_interface__["stream"]`` from the producer (cupy,
790	          torch, jax, etc.) and arrange for the first cvcuda operator to
791	          insert the proper ``cudaStreamWaitEvent`` before reading the data.
792	          No user-side ``synchronize()`` call is required.
793	        * On **output**, tensors returned by ``cvcuda.Tensor.cuda()`` /
794	          ``cvcuda.Image.cuda()`` populate ``__cuda_array_interface__
795	          ["stream"]`` with the cvcuda stream the data was last written on,
796	          so downstream consumers can sync themselves.
797	
798	        Advanced usage:
799	
800	        * **Opt out of the implicit wait**: export your buffer with
801	          ``stream: -1`` in its CAI dict to tell cvcuda you've already
802	          synchronized; the first op then runs without an extra event.
803	        * **Legacy default stream**: if your producer uses v2 CAI (no
804	          ``stream`` field) or advertises ``stream: 1``, cvcuda waits on the
805	          legacy default stream.  This is the safe conservative default but
806	          forfeits concurrency with stream-0 work.
807	        * **Use the default stream**: ``cvcuda.Stream.default`` wraps stream
808	          0 and has the usual legacy-default blocking semantics; use it when
809	          you want implicit sync with everything else on stream 0 and don't
810	          need the concurrency of a dedicated stream.
811	        )pbdoc");
812	
813	    stream.def(py::init(&Stream::Create),
814	               "Create a new CUDA stream.  Streams created this way are non-blocking; "
815	               "cross-library synchronization is handled automatically via the CAI "
816	               "``stream`` field (see the class docstring).");
817	
818	    py::module_ internal = m.attr(INTERNAL_SUBMODULE_NAME);
819	    internal.def("syncAuxStream", &SyncAuxStream);
820	
821	    // Wrap the CUDA legacy default stream as `cvcuda.Stream.default` and seed
822	    // the per-thread stream stack so `cvcuda.Stream.current` has something to
823	    // return.
824	    //
825	    // Skipped on hosts with no CUDA device (CPU-only build/CI nodes,
826	    // CUDA_VISIBLE_DEVICES=""): wrapping stream 0 unavoidably touches the
827	    // CUDA runtime (e.g. the `Stream` ctor's cudaStreamGetFlags + aux-stream
828	    // bookkeeping), which fails without a driver-bound device. We also skip
829	    // registering the `current` static property in that case — there is no
830	    // sensible value, and exposing a getter that throws breaks introspection
831	    // tools (pybind11_stubgen, sphinx-autodoc) that walk class members.
832	    int deviceCount = 0;
833	    if (cudaError_t devCntErr = cudaGetDeviceCount(&deviceCount);
834	        devCntErr == cudaErrorNoDevice || devCntErr == cudaErrorStubLibrary)
835	    {
836	        (void)cudaGetLastError();
837	        deviceCount = 0;
838	    }
839	    std::shared_ptr<Stream> globalStream;
840	    if (deviceCount > 0)
841	    {
842	        stream.def_property_readonly_static(
843	            "current", [](py::object) { return Current().sharedStream(); },
844	            "Get the current CUDA stream for this thread.");
845	
846	        static priv::ExternalStream<priv::VOIDP> cudaDefaultStream(static_cast<cudaStream_t>(nullptr));
847	        globalStream = std::make_shared<Stream>(cudaDefaultStream);
848	        StreamStack::Instance().push(*globalStream);
849	        stream.attr("default") = globalStream;
850	    }
851	
852	    // Order from most specific to less specific
853	    ExportExternalStream<TORCH>(m);
854	    ExportExternalStream<CUPY>(m);
855	    ExportExternalStream<VOIDP>(m);
856	    ExportExternalStream<INT>(m);
857	
858	    fflush(stdout);
859	
860	    stream.def("__enter__", &Stream::activate, "Activate the CUDA stream as the current stream for this thread.")
861	        .def("__exit__", &Stream::deactivate, "Deactivate the CUDA stream as the current stream for this thread.")
862	        .def("sync", &Stream::sync, "Wait for all preceding CUDA calls in the current stream to complete.")
863	        .def("wait_stream", &Stream::wait_stream, py::arg("other"),
864	             "Insert a dependency on 'other' into this stream. All subsequent work enqueued on this stream "
865	             "will wait until all work currently enqueued on 'other' has completed. "
866	             "Calling wait_stream(self) is a no-op. "
867	             "Cross-device usage is not supported and will raise a CUDA error.")
868	        .def("__int__", &Stream::pyhandle, "Cast the CUDA stream object to an integer handle.")
869	        .def("__repr__", &util::ToString<Stream>, "Return a string representation of the CUDA stream object.")
870	        .def_property_readonly("handle", &Stream::pyhandle, "Get the integer handle for the CUDA stream object.")
871	        .def_property_readonly("id", &Stream::id, "Get the unique ID for the CUDA stream object.");
872	
873	    // Make sure all streams we've created are synced when script ends.
874	    // Also make cleanup hold the globalStream reference during script execution.
875	    util::RegisterCleanup(m, [globalStream]() { CleanupAtExit(globalStream); });
876	}
877	
878	} // namespace nvcvpy::priv
